class Solution {
  public int numOfUnplacedFruits(int[] fruits, int[] baskets) {
    int unplaced = 0;
    for (int fruit : fruits) {
      boolean placed = false;
      for (int j = 0; j < baskets.length && !placed; j++) {
        if (baskets[j] >= fruit) {
          baskets[j] = 0;
          placed = true;
        }
      }
      if (!placed) unplaced++;
    }
    return unplaced;
  }
}
